// PreToolUse-Hook mit eigener Logik: sperrt nur das Einschalten von debug
let d = "";
process.stdin.on("data", c => d += c).on("end", () => {
  const i = JSON.parse(d).tool_input || {};
  const neu = (i.new_string || "") + (i.content || "");
  if (/"debug"\s*:\s*true/.test(neu)) {
    console.error("Blockiert vom Hook: debug darf nicht eingeschaltet werden.");
    process.exit(2);
  }
  process.exit(0);
});
